import { cookies } from 'next/headers';
import { createServerClient } from '@supabase/ssr';
import { supabaseConfig } from './server';

/**
 * Cookie-aware Supabase client for the OAuth start/callback route handlers.
 *
 * The PKCE code verifier generated by signInWithOAuth() is stored in a
 * short-lived cookie by @supabase/ssr; the callback route then uses the
 * same cookie jar to exchange ?code= for a session. Without the cookie
 * jar the verifier would be lost between the two requests.
 *
 * Note: next/headers cookies() is async in Next.js 15+/16 — hence the
 * await and the async factory signature.
 */
export async function getSupabaseRouteClient() {
  const config = supabaseConfig();
  if (!config) return null;

  const cookieStore = await cookies();

  return createServerClient(config.url, config.anonKey, {
    cookies: {
      getAll() {
        return cookieStore.getAll();
      },
      setAll(cookiesToSet) {
        try {
          cookiesToSet.forEach(({ name, value, options }) => {
            cookieStore.set(name, value, options);
          });
        } catch {
          // Called from a Server Component context — safe to ignore;
          // our callers are Route Handlers where mutation is allowed.
        }
      },
    },
    auth: {
      flowType: 'pkce',
      detectSessionInUrl: false,
    },
  });
}
